public final class Downloader {
  public CompletableFuture<String> get(URI uri) {
    return CompletableFuture.supplyAsync(() -> read(uri));   // read() wraps IOException
  }

  public void getThen(URI uri, Consumer<String> onDone, Consumer<Throwable> onError) {
    get(uri).whenComplete((body, err) -> {
      if (err != null) onError.accept(err); else onDone.accept(body);
    });
  }
}
